const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A polygon representing the Petén Department in Guatemala.
  const aoi = ee.Geometry.Polygon([[
    [-91.44, 17.89], [-89.37, 17.89], [-89.37, 15.82], [-91.44, 15.82], [-91.44, 17.89]
  ]]);

  // 2. Data Acquisition
  // Use the Hansen Global Forest Change dataset, which provides tree cover for 2000 and loss by year.
  // This is a single, pre-processed image, so no collection or cloud masking is needed.
  const gfc = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Define a forest threshold (e.g., >30% tree cover).
  const forestThreshold = 30;

  // 3. Processing
  // Create a mask for areas that were forest in the year 2000 (our baseline for 2001).
  const treeCover2000 = gfc.select('treecover2000');
  const forest2001Mask = treeCover2000.gt(forestThreshold);

  // Identify pixels that experienced loss at any point between 2001 and 2023.
  const loss = gfc.select('loss');
  const lossInPeriod = loss.eq(1);

  // Identify the forest area remaining in 2023 by removing lost areas from the 2001 baseline.
  const forest2023Mask = forest2001Mask.and(lossInPeriod.not());

  // Use ee.Image.pixelArea() to calculate the area of each pixel in square kilometers.
  const pixelArea = ee.Image.pixelArea().divide(1000000); // Convert from m^2 to km^2

  // Calculate the total forest area in 2001.
  const area2001Image = pixelArea.updateMask(forest2001Mask);
  const stats2001 = area2001Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e10
  });

  // Calculate the total forest area in 2023.
  const area2023Image = pixelArea.updateMask(forest2023Mask);
  const stats2023 = area2023Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e10
  });

  // 4. Calculation
  const forestArea2001 = stats2001.getNumber('area').getInfo();
  const forestArea2023 = stats2023.getNumber('area').getInfo();

  // 5. Validation & Final Answer
  if (forestArea2001 === null || forestArea2023 === null) {
      console.log('Calculation failed: Could not retrieve area statistics.');
      console.log('C3');
      return;
  }

  if (forestArea2001 === 0) {
      console.log('No valid forest pixels found for the baseline year 2001 in the specified region.');
      console.log('C2');
      return;
  }

  const change = forestArea2023 - forestArea2001;
  const percentChange = (change / forestArea2001) * 100;

  console.log(`Initial forest area (2001): ${forestArea2001.toFixed(2)} sq km`);
  console.log(`Final forest area (2023): ${forestArea2023.toFixed(2)} sq km`);
  console.log(`Forest cover change: ${change.toFixed(2)} sq km (${percentChange.toFixed(2)}%)`);

  if (forestArea2023 < forestArea2001) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
